    10	    public ClaimOffice(Customer customer) {
    11	        this.policyWideModifiers = new PolicyWideModifiers(customer);
    12	    }
    13	
    14	    /**
    15	     * The policy base premium is the sum of the base premiums of the main items
    16	     * and of the components, each priced by its own MHPCO pricing policy.
    17	     *
    18	     * The MHPCO names this amount in its own rules, so it is observable inside
    19	     * the domain; it is not part of what the office offers a caller, which is
    20	     * a quote.
    21	     */
    22	    int basePremium(List<Item> items) {
    23	        return MainItemPricing.mainItemsBasePremium(items)
    24	                + ComponentPricing.componentsBasePremium(items);
    25	    }
    26	
    27	    /**
    28	     * Item-specific modifiers apply to the base premium of the affected item,
    29	     * not to the policy total.
    30	     */
    31	    BigDecimal premiumAfterItemModifiers(List<Item> items) {
    32	        return BigDecimal.valueOf(basePremium(items))
    33	                .add(ItemRiskSurcharges.totalItemSurcharges(items));
    34	    }
    35	
    36	    /**
    37	     * The MHPCO issues a policy over the items it has agreed to cover.
    38	     */
    39	    public Policy insure(List<Item> items) {
    40	        return new Policy(accepted(items));
    41	    }
    42	
    43	    /**
    44	     * The items the MHPCO agrees to cover. The office declines the whole
    45	     * request rather than working around an item it does not insure, and it
    46	     * decides this the same way whether it is quoting for the items or issuing
    47	     * a policy over them.
    48	     */
    49	    private static List<Item> accepted(List<Item> items) {
    50	        InsurableItems.requireAllInsurable(items);
    51	        return items;
    52	    }
    53	
    54	    /**
    55	     * What the MHPCO would charge to insure these items, priced only for items
    56	     * the office has accepted.
    57	     *
    58	     * The MHPCO assembles the premium from a base premium and two families of
    59	     * modifier. Neither family is measured against the other's amounts: the
    60	     * item-specific risk surcharges are measured against the base premium of
    61	     * each affected item, the policy-wide modifiers against the policy base
    62	     * premium as a whole. Both are therefore added to the policy base premium
    63	     * side by side rather than in sequence, and the processing fee is added at
    64	     * the very end.
    65	     */
    66	    public int quote(List<Item> items) {
    67	        List<Item> insuredItems = accepted(items);
    68	        BigDecimal policyBasePremium = BigDecimal.valueOf(basePremium(insuredItems));
    69	        BigDecimal quotedPremium = premiumAfterItemModifiers(insuredItems)
    70	                .add(policyWideModifiers.totalPolicyModifiers(policyBasePremium))
    71	                .add(BigDecimal.valueOf(PROCESSING_FEE_IN_G));
    72	        policyWideModifiers.recordContractIssued();
    73	        return MhpcoFavour.roundedOwedToTheOffice(quotedPremium);
    74	    }
    75	}
