     3	/**
     4	 * A policy the MHPCO has issued over a list of insured items: what the office
     5	 * covers, and what the covered items are insured for.
     6	 *
     7	 * How far beyond the insurance sum the office will pay out, and what claims
     8	 * leave of that, is a separate decision, made by {@link PayoutCap}; which
     9	 * covered item a reported damage was suffered by is another, made by
    10	 * {@link CoveredItems}.
    11	 */
    12	public final class Policy {
    13	
    14	    private final CoveredItems coveredItems;
    15	
    16	    private final PayoutCap payoutCap;
    17	
    18	    public Policy(List<Item> insuredItems) {
    19	        this.coveredItems = new CoveredItems(insuredItems);
    20	        this.payoutCap = PayoutCap.overInsuranceSum(insuranceSum());
    21	    }
    22	
    23	    /**
    24	     * What the covered items are insured for, all together.
    25	     */
    26	    public int insuranceSum() {
    27	        return coveredItems.insuranceSum();
    28	    }
    29	
    30	    /**
    31	     * The most the MHPCO will pay out over the life of this policy, as it was
    32	     * set when the policy was issued. Claims settled since have not moved it;
    33	     * what they have left of it is {@link Claim#remainingCap()}.
    34	     */
    35	    public int cap() {
    36	        return payoutCap.total();
    37	    }
    38	
    39	    /**
    40	     * The MHPCO settles an incident against this policy: it reimburses the
    41	     * incident as far as the policy's cap still reaches, and reports what the
    42	     * settlement leaves of that cap.
    43	     */
    44	    public Claim claim(Incident incident) {
    45	        int payout = payoutCap.drawDown(Reimbursement.forIncident(incident, coveredItems));
    46	        return new Claim(payout, payoutCap.remaining());
    47	    }
    48	}
